import user_icon from '../img/user_icon.png'
import { Flex } from 'antd';
// import { messages } from 'react-stomp-hooks/dist/mock/client';


const  Home = () => {
    const navigate = useNavigate();
    const location = useLocation();
    const log = location.state?.from?.pathname || "/logout";
    let currentUser = 'Jon-Thomas2';
    let email = 'jt010051@gmail.com';
    let phone = ''
    const [thisMessage, setThisMessage] = useState('')
  const[name, setName] = useState('')
    const [activeUser, setActiveUser] = useState(false);
    const [listOfUsers, setListOfUsers] = useState([])
	const [selectedUser, setSelectedUser] = useState('')
    const [recievedMessages, setRecievedMessages] = useState(false)
const [newMessages, setNewMessages] = useState(false)
const[message, setMessage] = useState('')
const[idArr, setIdArr] = useState([])

const [userChatResponse, setUserChatResponse] = useState({});
const [currentData, setCurrentData] = useState({});

     const findAndDisplayConnectedUsers = async(e) =>{

        try{
        const connectedUsersList  = await axios.get('user/allUsers');
        setListOfUsers(connectedUsersList.data

            .filter( user => user.email !== email)
            .filter( user => user.phone !== phone)

            .map(user => user.firstName))
        }
        catch (err) {
            console.log(err);

        }

    }
    const   fetchAndDisplayUserChat = async()=>{


const response = await axios.get(`/messages/${currentUser}/${selectedUser}`)
setUserChatResponse(response)



// setCurrentData(response.data)

    }


    const stompClient = useStompClient();
	useSubscription(`/user/public`)
	useSubscription(`/user/${currentUser}/queue/messages`, (message2) => {
       let newMessage = message2.body.split("\"content\":")[1];
    let nextString = newMessage.split("}")[0]
       let finalStr = nextString.replaceAll("\"", "");
       setMessage(finalStr)
        let newObj ={
            id : currentData.length + 1,
            chatId : 'Jon-Thomas_Jon-Thomas2',
            content : finalStr,
            senderId : selectedUser,
             recipientId : currentUser,
            timeStamp : new Date
        }
        let data = {}
        if(currentData) 
         data = currentData

        data.push(newObj)
        console.log(newObj);

        setCurrentData(data)
        setRecievedMessages(true)

    }

 )


  if(stompClient){
    stompClient.publish("/app/user.addUser",
        {},
        JSON.stringify({firstName: currentUser, status:'ONLINE'})
        )
  }
    const publishMessage = (e) => {

        if(stompClient) {
            const chatMessage = {
                senderId: currentUser,
                recipientId: selectedUser,
                content: thisMessage,
                timeStamp: new Date() 
            }
          stompClient.publish({destination: '/app/chat', body: JSON.stringify(chatMessage)})
        //   displayMessage(currentUser, thisMessage)



        let data = userChatResponse.data
        data.push(chatMessage)

        setCurrentData(data)


        document.getElementById("message").value = '';

        setNewMessages(true)

        }
      }
if (!currentUser) {
    currentUser = localStorage.getItem("phone");
}


const userDetailsApi = `user/userDetails/${currentUser}`



const logout =()=>{
    navigate(log, { replace: true });

}

useEffect(()=>{
findAndDisplayConnectedUsers()

},[])
useEffect(()=>{
if(activeUser){
    fetchAndDisplayUserChat()
}
},[selectedUser])

const recievedMessgs = () =>{

if(Object.keys(currentData).length !== 0  
) return(
    currentData.map((data)=>{


                return(
<div className={['message', data.senderId === currentUser 
    || !message? 'sender' : 'receiver'].join(" ")}>
<p>
{ data.content }


</p>
</div>
                )          
            })
)
}

useEffect(()=>{
  if(activeUser && newMessages)  fetchAndDisplayUserChat()




    setNewMessages(false)
},[newMessages])





